#include <zephyr/kernel.h>
#include <zephyr/ztest.h>

#define STACK_SIZE (512 + K_THREAD_STACK_SIZEOF(k_mem_slab_t))
#define NUM_BLOCKS 2
#define BLOCK_SIZE 64

K_MEM_SLAB_DEFINE(mslab1, BLOCK_SIZE, NUM_BLOCKS, 4);
static void *blocks[NUM_BLOCKS]; /* To hold allocated blocks */

/*
 * This function tests the k_mem_slab_alloc timeout behavior.
 * It is expected to fill the slab, then attempt an allocation with a timeout,
 * expecting it to fail with -EAGAIN.
 */
static void tmslab_alloc_wait_timeout(void) {
    void *block;
    int ret;

    /* 1. Allocate all blocks from mslab1 to make it full. */
    for (int i = 0; i < NUM_BLOCKS; i++) { /* Ensure loop iterates NUM_BLOCKS times */
        ret = k_mem_slab_alloc(&mslab1, &blocks[i], K_NO_WAIT);
        zassert_equal(ret, 0, "Failed to allocate block %d initially", i);
    }

    /* At this point, mslab1 should be full. */
    /* 2. Attempt to allocate another block with a timeout. */
    /* This call should fail with -EAGAIN because the slab is full and the timeout expires. */
    ret = k_mem_slab_alloc(&mslab1, &block, K_MSEC(100)); /* TIMEOUT is K_MSEC(100) */
    zassert_equal(ret, -EAGAIN, "k_mem_slab_alloc(&mslab1, &block, TIMEOUT) == -EAGAIN is false");

    /* Clean up: free the blocks */
    for (int i = 0; i < NUM_BLOCKS; i++) {
        k_mem_slab_free(&mslab1, blocks[i]);
    }
}

/* Test thread for priority waiting scenario */
K_THREAD_STACK_DEFINE(tstack, STACK_SIZE);
struct k_thread tdata;
static K_SEM_DEFINE(thread_sem, 0, 1);

void high_prio_thread_entry(void *p1, void *p2, void *p3) {
    ARG_UNUSED(p1); ARG_UNUSED(p2); ARG_UNUSED(p3);

    /* Wait for the low-priority thread to start waiting */
    k_sem_take(&thread_sem, K_FOREVER);

    /* Free a block, allowing the waiting thread to proceed */
    k_mem_slab_free(&mslab1, blocks[0]); /* Free one of the blocks allocated by main thread */
}

/*
 * This function tests a scenario where a low-priority thread waits for a block,
 * and a high-priority thread frees it.
 */
static void test_mslab_alloc_wait_prio_impl(void) {
    int ret;
    void *block;

    /* 1. Allocate all blocks except one from mslab1 */
    for (int i = 0; i < NUM_BLOCKS - 1; i++) {
        ret = k_mem_slab_alloc(&mslab1, &blocks[i], K_NO_WAIT);
        zassert_equal(ret, 0, "Failed to allocate block %d initially", i);
    }

    /* 2. Create a high-priority thread that will free a block */
    k_thread_create(&tdata, tstack, STACK_SIZE,
                    high_prio_thread_entry, NULL, NULL, NULL,
                    K_PRIO_PREEMPT(0), 0, K_NO_WAIT);
    k_thread_name_set(&tdata, "high_prio_thread");

    /* 3. Attempt to allocate the last block with a timeout from the current (lower priority) thread. */
    /* This thread will wait. */
    k_sem_give(&thread_sem); /* Signal high-priority thread to free a block */

    ret = k_mem_slab_alloc(&mslab1, &block, K_MSEC(500)); /* Wait for a block */
    zassert_equal(ret, 0, "Allocation in low-priority thread failed");

    /* Clean up */
    k_mem_slab_free(&mslab1, block);
    for (int i = 1; i < NUM_BLOCKS - 1; i++) { /* blocks[0] was freed by high_prio_thread_entry */
        k_mem_slab_free(&mslab1, blocks[i]);
    }
    k_thread_abort(&tdata); /* Ensure thread is cleaned up */
}

/* Test setup and teardown */
static void mslab_concept_setup(void) {
    /* No specific setup needed beyond K_MEM_SLAB_DEFINE */
}

static void mslab_concept_teardown(void) {
    /* No specific teardown needed if tests clean up after themselves */
}

ZTEST_SUITE(mslab_concept, NULL, mslab_concept_setup, NULL, mslab_concept_teardown, NULL);

ZTEST(mslab_concept, test_mslab_alloc_wait_prio) {
    /* The error log points to tmslab_alloc_wait_timeout as the source of the assertion failure. */
    /* This test likely combines the timeout behavior with priority waiting. */
    tmslab_alloc_wait_timeout();
    test_mslab_alloc_wait_prio_impl();
}
